--- `scan(init, body, length)`. `body`'s inputs are, in creation order,
--- the carry, each broadcast, then each per-step slice of `xs`; its one
--- output is the next carry. The body graph is **consumed**.
--- `trajectory` returns every carry stacked (`[length, …init]`).
function M.Graph:scan(init, body, length, opts)
  opts = opts or {}
  local rc, r0_0 = core.rlx_graph_scan(self.handle, init, body.handle, length, (opts.xs == nil and {} or opts.xs), #(opts.xs == nil and {} or opts.xs), (opts.bcasts == nil and {} or opts.bcasts), #(opts.bcasts == nil and {} or opts.bcasts), (opts.checkpoints == nil and 0 or opts.checkpoints), (opts.trajectory == nil and false or opts.trajectory))
  S.check(rc)
  return r0_0
end

