  local rc, r0_0 = core.rlx_graph_custom_fn(self.handle, inputs, #inputs, fwd_body.handle, opts.vjp_body and opts.vjp_body.handle or nil, opts.jvp_body and opts.jvp_body.handle or nil)
  S.check(rc)
  return r0_0
end

